 17		"github.com/entireio/cli/cmd/entire/cli/agent"
 18		"github.com/entireio/cli/cmd/entire/cli/entiredir"
 19		"github.com/entireio/cli/cmd/entire/cli/paths"
 20	
 21		"github.com/sergi/go-diff/diffmatchpatch"
 22	)
 23	
 24	// tunedRunner is one accepted rewrite: the runner, its new file bytes, and the
 25	// new template on its own. The template is kept because --dry-run diffs the
 26	// template rather than the JSON file.
 27	type tunedRunner struct {
 28		runner   tuneRunner
 29		newRaw   []byte
 30		template string
 31	}
 32	
 33	// runTuning runs the prompt through the configured summary provider
 34	// (prompt -> text) and turns the runner-id -> template map it returns into
 35	// accepted rewrites. Rejections — out of scope, invalid template, unpatchable
 36	// file — are reported on errW and counted rather than returned, so one bad
 37	// runner does not sink the rest. Nothing is written here: the caller chooses
 38	// between applying the changes and previewing them.
 39	func runTuning(ctx context.Context, errW io.Writer, runners []tuneRunner, prompt, debugDir string) (changes []tunedRunner, skipped int, err error) {
 40		// Reuse the summary-provider resolution (selection + persistence), but pull
 41		// the raw TextGenerator rather than provider.Generator: the latter is a
 42		// summarize.Generator that turns a transcript Input into a checkpoint
 43		// Summary, whereas we need plain prompt->text generation here.
 44		provider, err := resolveCheckpointSummaryProvider(ctx, errW)
 45		if err != nil {
 46			return nil, 0, err
 47		}
 48		ag, err := agent.Get(provider.Name)
 49		if err != nil {
 50			return nil, 0, fmt.Errorf("loading provider %s: %w", provider.Name, err)
 51		}
 52		textGen, ok := agent.AsTextGenerator(ag)
 53		if !ok {
 54			return nil, 0, fmt.Errorf("provider %s cannot generate text", provider.Name)
 55		}
 56	
 57		stop := startSpinner(errW, fmt.Sprintf("Tuning %d runner(s) with %s", len(runners), provider.DisplayName))
 58		out, err := textGen.GenerateText(ctx, prompt, provider.Model)
 59		stop(err == nil)
 60		if err != nil {
 61			return nil, 0, fmt.Errorf("agent run failed: %w", err)
 62		}
 63		if debugDir != "" {
 64			writeTuneDebug(errW, debugDir, "response.txt", out)
 65		}
 66	
 67		templates, err := parseTuneOutput(out)
 68		if err != nil {
 69			return nil, 0, err
 70		}
 71		changes, skipped = classifyTuneProposals(errW, runners, templates)
 72		return changes, skipped, nil
 73	}
 74	
 75	// classifyTuneProposals turns the model's runner-id -> template map into the
 76	// rewrites that will actually be used, reporting each rejection on errW and
 77	// counting it. It is separate from the provider call so the accept/reject rules
 78	// can be tested against canned proposals.
 79	//
 80	// A rejection is never fatal: one unusable proposal must not cost the other
 81	// runners their tailoring.
 82	func classifyTuneProposals(errW io.Writer, runners []tuneRunner, templates map[string]string) (changes []tunedRunner, skipped int) {
 83		byID := make(map[string]tuneRunner, len(runners))
 84		for _, r := range runners {
 85			byID[normalizeRunnerID(r.ID)] = r
 86		}
 87	
 88		// Sorted so the skip/note messages and the preview diff come out in a stable
 89		// order rather than in Go's randomized map order.
 90		for _, id := range slices.Sorted(maps.Keys(templates)) {
 91			tmpl := templates[id]
 92			r, ok := byID[normalizeRunnerID(id)]
 93			if !ok {
 94				fmt.Fprintf(errW, "skip %q: not a runner in scope\n", id)
 95				skipped++
 96				continue
 97			}
 98			if err := validateNewTemplate(r.Template, tmpl); err != nil {
 99				fmt.Fprintf(errW, "skip %s: %v\n", r.ID, err)
100				skipped++
101				continue
102			}
103			if dropped := droppedPlaceholders(r.Template, tmpl); len(dropped) > 0 {
104				fmt.Fprintf(errW, "note: %s no longer references %v\n", r.ID, dropped)
105			}
106			newRaw, err := replaceRunnerTemplate(r.Raw, tmpl)
107			if err != nil {
108				fmt.Fprintf(errW, "skip %s: %v\n", r.ID, err)
109				skipped++
110				continue
111			}
112			if bytes.Equal(newRaw, r.Raw) {
113				continue // model returned the current template verbatim — benign no-op
114			}
115			changes = append(changes, tunedRunner{runner: r, newRaw: newRaw, template: tmpl})
116		}
117		return changes, skipped
118	}
119	
120	// applyTunedRunners writes each accepted rewrite over its runner file.
121	// createdIDs are runners this invocation just scaffolded from defaults; any of
122	// those left un-tailored is flagged so it is not committed as if it were
123	// repo-specific.
124	func applyTunedRunners(w, errW io.Writer, repoRoot string, changes []tunedRunner, skipped int, createdIDs []string) error {
125		root, err := entiredir.OpenAt(repoRoot)
126		if err != nil {
127			return fmt.Errorf("open %s: %w", paths.EntireDir, err)
128		}
129	
130		tailored := make(map[string]bool, len(changes))
131		for _, c := range changes {
132			if err := entiredir.WriteFile(root, c.runner.Name, c.newRaw, 0o644); err != nil {
133				return fmt.Errorf("writing %s: %w", c.runner.Path, err)
134			}
135			fmt.Fprintf(w, "updated %s\n", filepath.Base(c.runner.Path))
136			tailored[normalizeRunnerID(c.runner.ID)] = true
137		}
138	
139		switch {
140		case len(changes) > 0:
141			fmt.Fprintf(w, "\nUpdated %d runner(s). Review with: git diff %s\n",
142				len(changes), filepath.Join(paths.EntireDir, runnersName))
143		case len(createdIDs) == 0 && skipped > 0:
144			// Existing runners, model proposed templates, all rejected — a failed run.
145			// (When onboarding just created the set, an un-tailored runner is reported
146			// below as a generic default instead, which is more actionable.)
147			return fmt.Errorf("model proposed %d template(s) but all were rejected or out of scope (see messages above)", skipped)
148		case len(createdIDs) == 0:
149			fmt.Fprintln(w, "No runner changes proposed.")
150		}
151	
152		// Runners onboarding scaffolded but tailoring did not change remain the
153		// generic defaults. Those are working minimal prompts (valid output
154		// contract), so they are committable as-is — just note which are generic.
155		if untailored := untailoredRunners(createdIDs, tailored); len(untailored) > 0 {
156			fmt.Fprintf(errW, "\n%d runner(s) kept as working defaults (generic, not tailored to this repo): %s\n",
157				len(untailored), strings.Join(untailored, ", "))
158			fmt.Fprintln(errW, "They are functional as-is; re-run `entire runner setup -y` to tailor them.")
159		}
160		return nil
161	}
162	
163	// previewTunedRunners prints what tailoring would change and writes nothing.
164	// It diffs each runner's prompt template rather than its JSON file: the
165	// template is the only field that changes and it is stored as one long JSON
166	// string, so a file-level diff would be a single unreadable line.
167	func previewTunedRunners(w, errW io.Writer, runners []tuneRunner, changes []tunedRunner, skipped int, haveRunners bool) {
168		if !haveRunners {
169			fmt.Fprintf(errW, "This repo has no runners yet and --dry-run creates none, so the preview is against the %d embedded default(s).\n", len(runners))
170		}
171		for _, c := range changes {
172			fmt.Fprintf(w, "=== %s — prompt.template would change ===\n", c.runner.ID)
173			fmt.Fprint(w, renderTemplateDiff(c.runner.Template, c.template))
174			fmt.Fprintln(w)
175		}
176	
177		switch {
178		case len(changes) > 0:
179			fmt.Fprintf(errW, "%d of %d runner(s) would change", len(changes), len(runners))
180			if skipped > 0 {
181				fmt.Fprintf(errW, ", %d proposal(s) rejected", skipped)
182			}
183			fmt.Fprintln(errW, ". Nothing was written — re-run with --yes to apply.")
184		case skipped > 0:
185			fmt.Fprintf(errW, "No runner would change: all %d proposal(s) were rejected or out of scope (see messages above).\n", skipped)
186		default:
187			fmt.Fprintln(errW, "No runner changes proposed.")
188		}
189	}
190	
191	// diffContextLines is how many unchanged template lines to keep either side of
192	// a change in the --dry-run preview. A tailored template is mostly rewritten,
193	// so the point of the collapse is the long unchanged tail (the output-JSON
194	// contract), not economy on the changed part.
195	const diffContextLines = 3
196	
197	// renderTemplateDiff renders a line-level diff of two prompt templates, with
198	// unchanged runs longer than twice the context collapsed to a count.
199	// diffmatchpatch is character-oriented, so the templates are folded to one
200	// char per line first (the DiffLinesToChars/DiffCharsToLines pattern, as in
201	// strategy/manual_commit_attribution.go).
202	func renderTemplateDiff(oldText, newText string) string {
203		dmp := diffmatchpatch.New()
204		a, b, lines := dmp.DiffLinesToChars(oldText, newText)
205		diffs := dmp.DiffCharsToLines(dmp.DiffMain(a, b, false), lines)
206	
207		var out strings.Builder
208		for _, d := range diffs {
209			switch d.Type {
210			case diffmatchpatch.DiffInsert:
211				writeDiffLines(&out, "+", splitLines(d.Text))
212			case diffmatchpatch.DiffDelete:
213				writeDiffLines(&out, "-", splitLines(d.Text))
214			case diffmatchpatch.DiffEqual:
215				ls := splitLines(d.Text)
216				if len(ls) <= 2*diffContextLines {
217					writeDiffLines(&out, " ", ls)
218					continue
219				}
220				writeDiffLines(&out, " ", ls[:diffContextLines])
221				fmt.Fprintf(&out, "@@ %d unchanged line(s) @@\n", len(ls)-2*diffContextLines)
222				writeDiffLines(&out, " ", ls[len(ls)-diffContextLines:])
223			}
224		}
225		return out.String()
226	}
227	
228	func writeDiffLines(out *strings.Builder, prefix string, lines []string) {
229		for _, line := range lines {
230			out.WriteString(prefix)
231			out.WriteString(line)
232			out.WriteByte('\n')
233		}
234	}
235	
236	// splitLines splits a diff chunk into lines, dropping the empty element a
237	// trailing newline produces so it is not rendered as a blank diff line.
238	func splitLines(s string) []string {
239		lines := strings.Split(s, "\n")
240		if len(lines) > 0 && lines[len(lines)-1] == "" {
241			lines = lines[:len(lines)-1]
242		}
243		return lines
244	}
245	
246	// parseTuneOutput extracts the runner-id -> new-template map the tuning model
247	// is instructed to emit as a single JSON object. The model may wrap the object
248	// in prose or code fences, so we slice from the first "{" to the last "}". An
249	// empty object ({}) is valid: the model is told to omit unchanged runners, so
250	// "{}" is the legitimate "no changes" result, not an error.
251	func parseTuneOutput(text string) (map[string]string, error) {
252		obj := extractJSONObject(text)
253		if obj == "" {
254			return nil, errors.New("no JSON object found in model output")
255		}
256		var m map[string]string
257		if err := json.Unmarshal([]byte(obj), &m); err != nil {
258			return nil, fmt.Errorf("parse model output as {runner: template}: %w", err)
259		}
260		return m, nil
261	}
262	
263	var placeholderRe = regexp.MustCompile(`{{[^{}]+}}`)
264	
265	// validateNewTemplate rejects a rewritten template that is empty or that
266	// introduces a {{placeholder}} not present in the original. An invented
267	// placeholder is unsafe: the backend only substitutes the known set, so a new
268	// token renders as literal "{{junk}}" in the prompt. Dropping a placeholder is
269	// safe — it just leaves a substitution slot unused (e.g. the model commonly
270	// drops the cosmetic {{branch}} since the diff is taken against HEAD) — so
271	// drops are allowed here and surfaced as a note by the caller instead.
272	func validateNewTemplate(oldTemplate, newTemplate string) error {
273		if strings.TrimSpace(newTemplate) == "" {
274			return errors.New("rewritten template is empty")
275		}
276		oldSet := placeholderSet(oldTemplate)
277		var added []string
278		for ph := range placeholderSet(newTemplate) {
279			if !oldSet[ph] {
280				added = append(added, ph)
281			}
282		}
283		sort.Strings(added)
284		if len(added) > 0 {
285			return fmt.Errorf("rewritten template added unknown placeholder(s): %s", strings.Join(added, ", "))
286		}
287		return nil
288	}
289	
290	// untailoredRunners returns the created runner IDs that tuning did NOT tailor
291	// (still generic defaults), sorted. These were scaffolded by onboarding but
292	// left unchanged — skipped, omitted by the model, or returned verbatim — so
293	// they must not be presented as repo-tailored.
294	func untailoredRunners(createdIDs []string, tailored map[string]bool) []string {
295		var out []string
296		for _, id := range createdIDs {
297			if !tailored[normalizeRunnerID(id)] {
298				out = append(out, id)
299			}
300		}
301		sort.Strings(out)
302		return out
303	}
304	
305	// droppedPlaceholders returns the placeholders present in oldTemplate but not in
306	// newTemplate, sorted. Used to inform the user when a rewrite stops using one.
307	func droppedPlaceholders(oldTemplate, newTemplate string) []string {
308		newSet := placeholderSet(newTemplate)
309		var dropped []string
310		for ph := range placeholderSet(oldTemplate) {
311			if !newSet[ph] {
312				dropped = append(dropped, ph)
313			}
314		}
315		sort.Strings(dropped)
316		return dropped
317	}
318	
319	func placeholderSet(s string) map[string]bool {
320		set := make(map[string]bool)
321		for _, ph := range placeholderRe.FindAllString(s, -1) {
322			set[ph] = true
323		}
324		return set
325	}
326	
327	// extractJSONObject returns the outermost {...} span in text, after stripping
328	// any surrounding markdown code fences. Returns "" when none is found.
329	func extractJSONObject(text string) string {
330		text = stripCodeFences(strings.TrimSpace(text))
331		start := strings.Index(text, "{")
332		end := strings.LastIndex(text, "}")
333		if start < 0 || end <= start {
334			return ""
335		}
336		return text[start : end+1]
337	}
338	
339	func stripCodeFences(text string) string {
340		if !strings.HasPrefix(text, "```") {
341			return text
342		}
343		// Drop the opening fence line (``` or ```json) and the closing fence.
344		if nl := strings.IndexByte(text, '\n'); nl >= 0 {
345			text = text[nl+1:]
346		}
347		if i := strings.LastIndex(text, "```"); i >= 0 {
348			text = text[:i]
349		}
350		return strings.TrimSpace(text)
351	}
352	
353	// replaceRunnerTemplate swaps only the prompt.template value inside a runner
354	// JSON document, leaving every other field and the file's formatting
355	// byte-for-byte intact. It works on the raw bytes (not a re-marshal) so unknown
356	// or backend-managed fields are never dropped and the git diff stays scoped to
357	// the prompt change. Returns the original bytes unchanged when newTemplate
358	// matches the current template.
359	func replaceRunnerTemplate(raw []byte, newTemplate string) ([]byte, error) {
360		var top map[string]json.RawMessage
361		if err := json.Unmarshal(raw, &top); err != nil {
362			return nil, fmt.Errorf("parse runner JSON: %w", err)
363		}
364		promptRaw, ok := top["prompt"]
365		if !ok {
366			return nil, errors.New("runner has no \"prompt\" object")
367		}
368		var promptObj map[string]json.RawMessage
369		if err := json.Unmarshal(promptRaw, &promptObj); err != nil {
370			return nil, fmt.Errorf("parse runner prompt object: %w", err)
371		}
372		// oldVal holds the original on-disk bytes of the template value, so it is a
373		// guaranteed substring of raw.
374		oldVal, ok := promptObj["template"]
375		if !ok {
376			return nil, errors.New("runner has no \"prompt.template\" field")
377		}
378	
379		newVal, err := encodeJSONString(newTemplate)
380		if err != nil {
381			return nil, err
382		}
383		if bytes.Equal(oldVal, newVal) {
384			return raw, nil
385		}
386	
387		if n := bytes.Count(raw, oldVal); n != 1 {
388			return nil, fmt.Errorf("expected exactly one occurrence of the current template, found %d", n)
389		}
390		out := bytes.Replace(raw, oldVal, newVal, 1)
391		if !json.Valid(out) {
392			return nil, errors.New("template replacement produced invalid JSON")
393		}
394		return out, nil
395	}
396	
397	// encodeJSONString encodes s as a JSON string without HTML escaping, so
398	// characters like <, >, and & stay literal — matching the style the runner
399	// files are authored in and keeping diffs minimal.
400	func encodeJSONString(s string) ([]byte, error) {
401		var buf bytes.Buffer
402		enc := json.NewEncoder(&buf)
403		enc.SetEscapeHTML(false)
404		if err := enc.Encode(s); err != nil {
405			return nil, fmt.Errorf("encode template string: %w", err)
406		}
407		return bytes.TrimRight(buf.Bytes(), "\n"), nil
408	}

